/* From Uiverse.io by catraco - Tags: icon, loader, animated, light&dark */
.__UIV_SCOPE__ .loader {
  --color: #a5a5b0;
  --size: 40px;
  position: relative;
  width: var(--size);
  height: var(--size);
}

.__UIV_SCOPE__ .loader span {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  border: 1px solid var(--color);
  border-bottom: 1px solid transparent;
  border-radius: 100%;
  animation: keyframes-rotate .8s infinite linear;
}

.__UIV_SCOPE__ .loader svg {
  width: 100%;
  height: 100%;
  padding: 25%;
  fill: var(--color);
  animation: keyframes-blink .8s infinite ease-in-out;
}

@keyframes keyframes-rotate {
  0% {
    transform: rotate(360deg);
  }
}

@keyframes keyframes-blink {
  50% {
    opacity: 0.8;
  }
}
